const ORIGIN='cloudflare-worker-consequence-evidence';
const routes=new Set(['/api/public/consequence-contracts','/api/public/consequence-due','/api/admin/consequence-contracts/lock','/api/admin/consequence-evidence','/api/admin/consequence-assessment']);
const dynamicRoutes=[/^\/api\/public\/consequence-contracts\/[^/]+$/];
const evidenceClasses=new Set(['official_record','court_record','regulator_record','corporate_filing','budget_contract','corroborated_reporting','counter_evidence','right_of_reply']);
const outcomeFindings=new Set(['supported','partially-supported','not-supported','mixed','too-early','insufficient-evidence','not-implemented']);
const headers={'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','X-Frame-Options':'SAMEORIGIN','Referrer-Policy':'strict-origin-when-cross-origin','X-Matrix-Origin':ORIGIN};
let schemaPromise;

export function isConsequenceEvidenceRoute(pathname=''){const path=String(pathname||'').replace(/\/+$/,'')||'/';return routes.has(path)||dynamicRoutes.some(pattern=>pattern.test(path));}
const json=(data,status=200)=>new Response(JSON.stringify(data,null,2),{status,headers});
const clean=(value,max=1600)=>String(value??'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,max);
const safeId=value=>clean(value,240).replace(/[^A-Za-z0-9._:-]/g,'-').replace(/-+/g,'-');
const array=value=>Array.isArray(value)?value:[];
const nowIso=()=>new Date().toISOString();
const newId=prefix=>`${prefix}-${crypto.randomUUID()}`;
const hasD1=env=>Boolean(env?.MEMBERS_DB&&typeof env.MEMBERS_DB.prepare==='function');
const first=statement=>statement.first();
const all=async statement=>{const result=await statement.all();return Array.isArray(result?.results)?result.results:[];};
const readBody=async request=>{try{return await request.json();}catch{return{};}};
function secureEqual(a,b){a=String(a||'');b=String(b||'');if(!a||a.length!==b.length)return false;let diff=0;for(let i=0;i<a.length;i+=1)diff|=a.charCodeAt(i)^b.charCodeAt(i);return diff===0;}
const adminAllowed=(request,env)=>Boolean(env?.ADMIN_API_TOKEN&&secureEqual(request.headers.get('x-admin-token')||'',env.ADMIN_API_TOKEN));
function externalUrl(value){try{const url=new URL(clean(value,1500));return ['http:','https:'].includes(url.protocol)?url.toString():'';}catch{return'';}}
function localRoute(value){const route=clean(value,800);if(!route)return'';const normalized=route.startsWith('/')?route:`/${route}`;return normalized.startsWith('//')||/^[a-z]+:/i.test(normalized)?'':normalized;}
async function hash(value){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(value||'')));return [...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,'0')).join('');}
async function audit(env,action,targetType,targetId,metadata={}){await env.MEMBERS_DB.prepare('INSERT INTO audit_log (id,actor_id,action,target_type,target_id,metadata_json,created_at) VALUES (?,?,?,?,?,?,?)').bind(newId('consequence-audit'),'consequence-evidence',action,targetType,targetId||null,JSON.stringify(metadata),nowIso()).run().catch(()=>null);}

async function ensureSchema(env){
  if(!hasD1(env))throw new Error('MEMBERS_DB unavailable');
  if(schemaPromise)return schemaPromise;
  schemaPromise=(async()=>{
    const statements=[
      `CREATE TABLE IF NOT EXISTS consequence_contract_terms (contract_id TEXT PRIMARY KEY,responsible_actor TEXT NOT NULL,authority_basis TEXT NOT NULL,stated_rationale TEXT NOT NULL,claimed_public_benefit TEXT NOT NULL,measurable_success_json TEXT NOT NULL DEFAULT '[]',primary_source_urls_json TEXT NOT NULL DEFAULT '[]',locked_by TEXT NOT NULL,locked_at TEXT NOT NULL,updated_at TEXT NOT NULL)`,
      `CREATE TABLE IF NOT EXISTS consequence_evidence_items (id TEXT PRIMARY KEY,contract_id TEXT NOT NULL,checkpoint_days INTEGER NOT NULL,evidence_class TEXT NOT NULL,title TEXT NOT NULL,source_url TEXT NOT NULL,published_at TEXT,establishes TEXT NOT NULL,does_not_establish TEXT NOT NULL,source_hash TEXT NOT NULL,review_status TEXT NOT NULL,submitted_by TEXT NOT NULL,created_at TEXT NOT NULL,reviewed_at TEXT,UNIQUE(contract_id,checkpoint_days,source_hash))`,
      `CREATE INDEX IF NOT EXISTS idx_consequence_evidence_checkpoint ON consequence_evidence_items(contract_id,checkpoint_days,review_status)`,
      `CREATE TABLE IF NOT EXISTS consequence_outcome_assessments (id TEXT PRIMARY KEY,contract_id TEXT NOT NULL,checkpoint_days INTEGER NOT NULL,version INTEGER NOT NULL,overall_finding TEXT NOT NULL,implementation_status TEXT NOT NULL,public_benefit_status TEXT NOT NULL,money_beneficiary_status TEXT NOT NULL,affected_groups_status TEXT NOT NULL,confidence INTEGER NOT NULL,summary TEXT NOT NULL,alternative_explanations_json TEXT NOT NULL DEFAULT '[]',falsifiers_tested_json TEXT NOT NULL DEFAULT '[]',evidence_ids_json TEXT NOT NULL DEFAULT '[]',publication_status TEXT NOT NULL,reviewed_by TEXT,reviewed_at TEXT,created_at TEXT NOT NULL,UNIQUE(contract_id,checkpoint_days,version))`,
      `CREATE INDEX IF NOT EXISTS idx_consequence_assessment_public ON consequence_outcome_assessments(publication_status,reviewed_at DESC)`
    ];
    for(const sql of statements)await env.MEMBERS_DB.prepare(sql).run();
    return true;
  })().catch(error=>{schemaPromise=null;throw error;});
  return schemaPromise;
}

async function currentContracts(env,limit=100){
  const rows=await all(env.MEMBERS_DB.prepare(`SELECT c.contract_id,c.title,c.route,c.action_date,c.source_url,c.evidence_route,c.accountability_question,c.evidence_boundary,c.terms_lock,c.outcome_verdict,c.current_version,c.next_checkpoint_days,c.next_due_at,c.review_state,c.updated_at,a.checkpoint_days assessment_checkpoint_days,a.version assessment_version,a.overall_finding assessment_finding,a.confidence assessment_confidence,a.summary assessment_summary,a.reviewed_at assessment_reviewed_at FROM consequence_contracts c LEFT JOIN consequence_outcome_assessments a ON a.id=(SELECT a2.id FROM consequence_outcome_assessments a2 WHERE a2.contract_id=c.contract_id AND a2.publication_status='published' ORDER BY a2.reviewed_at DESC LIMIT 1) WHERE c.active=1 ORDER BY c.action_date DESC LIMIT ?`).bind(limit));
  return rows.map(row=>({id:row.contract_id,title:row.title,route:row.route,actionDate:row.action_date,sourceUrl:row.source_url,evidenceRoute:row.evidence_route,accountabilityQuestion:row.accountability_question,evidenceBoundary:row.evidence_boundary,termsLock:row.terms_lock,outcomeVerdict:row.outcome_verdict,version:Number(row.current_version||1),nextCheckpointDays:row.next_checkpoint_days==null?null:Number(row.next_checkpoint_days),nextDueAt:row.next_due_at,reviewState:row.review_state,updatedAt:row.updated_at,latestAssessment:row.assessment_version?{checkpointDays:Number(row.assessment_checkpoint_days),version:Number(row.assessment_version),overallFinding:row.assessment_finding,confidence:Number(row.assessment_confidence),summary:row.assessment_summary,reviewedAt:row.assessment_reviewed_at}:null}));
}
async function listContracts(request,env){await ensureSchema(env);const url=new URL(request.url);const limit=Math.min(100,Math.max(1,Number(url.searchParams.get('limit')||50)));const items=await currentContracts(env,limit);return json({ok:true,count:items.length,items,generatedAt:nowIso()});}
async function contractDetail(env,contractId){await ensureSchema(env);const contract=await first(env.MEMBERS_DB.prepare('SELECT * FROM consequence_contracts WHERE contract_id=? LIMIT 1').bind(contractId));if(!contract)return json({ok:false,error:'Consequence contract not found'},404);const [terms,versions,queue,evidence,assessments]=await Promise.all([
  first(env.MEMBERS_DB.prepare('SELECT * FROM consequence_contract_terms WHERE contract_id=? LIMIT 1').bind(contractId)),
  all(env.MEMBERS_DB.prepare('SELECT content_hash,created_at FROM consequence_contract_versions WHERE contract_id=? ORDER BY created_at DESC LIMIT 50').bind(contractId)),
  all(env.MEMBERS_DB.prepare('SELECT checkpoint_key,days_after_action,due_at,review_question,status,review_summary,evidence_route,reviewed_by,reviewed_at,updated_at FROM consequence_review_queue WHERE contract_id=? ORDER BY days_after_action').bind(contractId)),
  all(env.MEMBERS_DB.prepare("SELECT id,checkpoint_days,evidence_class,title,source_url,published_at,establishes,does_not_establish,review_status,submitted_by,created_at,reviewed_at FROM consequence_evidence_items WHERE contract_id=? AND review_status='accepted' ORDER BY checkpoint_days,created_at").bind(contractId)),
  all(env.MEMBERS_DB.prepare("SELECT * FROM consequence_outcome_assessments WHERE contract_id=? AND publication_status='published' ORDER BY checkpoint_days,version").bind(contractId))
]);return json({ok:true,contract,terms:terms||null,versions,checkpoints:queue,evidence,assessments});}
async function dueQueue(env){await ensureSchema(env);const rows=await all(env.MEMBERS_DB.prepare("SELECT q.checkpoint_key,q.contract_id,c.title,q.days_after_action,q.due_at,q.review_question,q.status,q.evidence_route,q.updated_at FROM consequence_review_queue q JOIN consequence_contracts c ON c.contract_id=q.contract_id WHERE q.status IN ('due','evidence-collected','awaiting-editorial-review') ORDER BY q.due_at LIMIT 100"));return json({ok:true,count:rows.length,items:rows,generatedAt:nowIso()});}

async function lockTerms(request,env){if(!adminAllowed(request,env))return json({ok:false,error:'Administrator authorization required'},403);await ensureSchema(env);const body=await readBody(request);const contractId=safeId(body.contractId);const actor=clean(body.responsibleActor,300),authority=clean(body.authorityBasis,1200),rationale=clean(body.statedRationale,1800),benefit=clean(body.claimedPublicBenefit,1400);const success=array(body.measurableSuccess).map(item=>clean(item,700)).filter(Boolean);const sources=array(body.primarySourceUrls).map(externalUrl).filter(Boolean);if(!contractId||!actor||!authority||!rationale||!benefit||!success.length||!sources.length)return json({ok:false,error:'Contract, actor, authority, rationale, claimed benefit, measurable success criteria and primary source URLs are required'},400);const contract=await first(env.MEMBERS_DB.prepare('SELECT contract_id FROM consequence_contracts WHERE contract_id=? LIMIT 1').bind(contractId));if(!contract)return json({ok:false,error:'Consequence contract not found'},404);const stamp=nowIso();await env.MEMBERS_DB.prepare(`INSERT INTO consequence_contract_terms (contract_id,responsible_actor,authority_basis,stated_rationale,claimed_public_benefit,measurable_success_json,primary_source_urls_json,locked_by,locked_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?) ON CONFLICT(contract_id) DO UPDATE SET responsible_actor=excluded.responsible_actor,authority_basis=excluded.authority_basis,stated_rationale=excluded.stated_rationale,claimed_public_benefit=excluded.claimed_public_benefit,measurable_success_json=excluded.measurable_success_json,primary_source_urls_json=excluded.primary_source_urls_json,locked_by=excluded.locked_by,locked_at=excluded.locked_at,updated_at=excluded.updated_at`).bind(contractId,actor,authority,rationale,benefit,JSON.stringify(success),JSON.stringify(sources),clean(body.reviewedBy||'admin-api',180),stamp,stamp).run();await env.MEMBERS_DB.prepare("UPDATE consequence_contracts SET terms_lock='locked-primary-decision-record',updated_at=? WHERE contract_id=?").bind(stamp,contractId).run();await audit(env,'consequence.terms.locked','consequence_contract',contractId,{sources,success});return json({ok:true,locked:true,contractId});}
async function addEvidence(request,env){if(!adminAllowed(request,env))return json({ok:false,error:'Administrator authorization required'},403);await ensureSchema(env);const body=await readBody(request);const contractId=safeId(body.contractId),checkpointDays=Number(body.checkpointDays||0),evidenceClass=clean(body.evidenceClass,80),title=clean(body.title,500),sourceUrl=externalUrl(body.sourceUrl),establishes=clean(body.establishes,1800),doesNotEstablish=clean(body.doesNotEstablish,1800);if(!contractId||![30,90,365].includes(checkpointDays)||!evidenceClasses.has(evidenceClass)||!title||!sourceUrl||!establishes||!doesNotEstablish)return json({ok:false,error:'Contract, 30/90/365 checkpoint, valid evidence class, source, title, establishes and does-not-establish fields are required'},400);const contract=await first(env.MEMBERS_DB.prepare('SELECT contract_id FROM consequence_contracts WHERE contract_id=? LIMIT 1').bind(contractId));if(!contract)return json({ok:false,error:'Consequence contract not found'},404);const sourceHash=await hash(`${contractId}|${checkpointDays}|${sourceUrl}|${title}`),id=newId('consequence-evidence'),stamp=nowIso();const result=await env.MEMBERS_DB.prepare(`INSERT OR IGNORE INTO consequence_evidence_items (id,contract_id,checkpoint_days,evidence_class,title,source_url,published_at,establishes,does_not_establish,source_hash,review_status,submitted_by,created_at,reviewed_at) VALUES (?,?,?,?,?,?,?,?,?,?,'accepted',?,?,?)`).bind(id,contractId,checkpointDays,evidenceClass,title,sourceUrl,clean(body.publishedAt,80)||null,establishes,doesNotEstablish,sourceHash,clean(body.submittedBy||'admin-api',180),stamp,stamp).run();if(Number(result?.meta?.changes||0)<1)return json({ok:true,duplicate:true,contractId,checkpointDays});await env.MEMBERS_DB.prepare("UPDATE consequence_review_queue SET status='evidence-collected',evidence_route=?,updated_at=? WHERE checkpoint_key=?").bind(localRoute(body.evidenceRoute)||'/evidence-vault.html',stamp,`${contractId}:${checkpointDays}`).run();await audit(env,'consequence.evidence.accepted','consequence_contract',contractId,{checkpointDays,evidenceClass,sourceUrl});return json({ok:true,accepted:true,id,contractId,checkpointDays});}
async function publishAssessment(request,env){if(!adminAllowed(request,env))return json({ok:false,error:'Administrator authorization required'},403);await ensureSchema(env);const body=await readBody(request);const contractId=safeId(body.contractId),checkpointDays=Number(body.checkpointDays||0),finding=clean(body.overallFinding,80),summary=clean(body.summary,2600),reviewedBy=clean(body.reviewedBy,180),publicationStatus=body.publicationStatus==='published'?'published':'draft',confidence=Math.max(0,Math.min(100,Number(body.confidence||0))),evidenceIds=array(body.evidenceIds).map(safeId).filter(Boolean);if(!contractId||![30,90,365].includes(checkpointDays)||!outcomeFindings.has(finding)||!summary||!evidenceIds.length||!clean(body.implementationStatus,700)||!clean(body.publicBenefitStatus,700)||!clean(body.moneyBeneficiaryStatus,700)||!clean(body.affectedGroupsStatus,700))return json({ok:false,error:'A valid contract, checkpoint, finding, evidence set and all outcome dimensions are required'},400);const contract=await first(env.MEMBERS_DB.prepare('SELECT terms_lock,route FROM consequence_contracts WHERE contract_id=? LIMIT 1').bind(contractId));if(!contract)return json({ok:false,error:'Consequence contract not found'},404);if(contract.terms_lock!=='locked-primary-decision-record')return json({ok:false,error:'Primary decision terms must be locked before an outcome assessment can be issued'},409);if(publicationStatus==='published'&&!reviewedBy)return json({ok:false,error:'Published assessments require a named reviewer'},400);const placeholders=evidenceIds.map(()=>'?').join(',');const accepted=await first(env.MEMBERS_DB.prepare(`SELECT COUNT(*) count FROM consequence_evidence_items WHERE contract_id=? AND checkpoint_days=? AND review_status='accepted' AND id IN (${placeholders})`).bind(contractId,checkpointDays,...evidenceIds));if(Number(accepted?.count||0)!==evidenceIds.length)return json({ok:false,error:'Every cited evidence record must be accepted and belong to this contract checkpoint'},400);const current=await first(env.MEMBERS_DB.prepare('SELECT MAX(version) version FROM consequence_outcome_assessments WHERE contract_id=? AND checkpoint_days=?').bind(contractId,checkpointDays));const version=Number(current?.version||0)+1,stamp=nowIso(),id=newId('consequence-assessment');await env.MEMBERS_DB.prepare(`INSERT INTO consequence_outcome_assessments (id,contract_id,checkpoint_days,version,overall_finding,implementation_status,public_benefit_status,money_beneficiary_status,affected_groups_status,confidence,summary,alternative_explanations_json,falsifiers_tested_json,evidence_ids_json,publication_status,reviewed_by,reviewed_at,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,contractId,checkpointDays,version,finding,clean(body.implementationStatus,700),clean(body.publicBenefitStatus,700),clean(body.moneyBeneficiaryStatus,700),clean(body.affectedGroupsStatus,700),confidence,summary,JSON.stringify(array(body.alternativeExplanations).map(item=>clean(item,900)).filter(Boolean)),JSON.stringify(array(body.falsifiersTested).map(item=>clean(item,900)).filter(Boolean)),JSON.stringify(evidenceIds),publicationStatus,reviewedBy||null,publicationStatus==='published'?stamp:null,stamp).run();if(publicationStatus==='published')await env.MEMBERS_DB.batch([env.MEMBERS_DB.prepare("UPDATE consequence_review_queue SET status='reviewed',review_summary=?,evidence_route=?,reviewed_by=?,reviewed_at=?,updated_at=? WHERE checkpoint_key=?").bind(summary,localRoute(body.evidenceRoute)||'/evidence-vault.html',reviewedBy,stamp,stamp,`${contractId}:${checkpointDays}`),env.MEMBERS_DB.prepare('UPDATE consequence_contracts SET outcome_verdict=?,updated_at=? WHERE contract_id=?').bind(finding,stamp,contractId),env.MEMBERS_DB.prepare("INSERT OR IGNORE INTO consequence_events (id,event_key,contract_id,event_type,checkpoint_days,route,summary,evidence_route,created_at) VALUES (?,?,?,'checkpoint_assessed',?,?,?,?,?)").bind(`event:assessed:${contractId}:${checkpointDays}:v${version}`,`assessed:${contractId}:${checkpointDays}:v${version}`,contractId,checkpointDays,contract.route,summary,localRoute(body.evidenceRoute)||'/evidence-vault.html',stamp)]);else await env.MEMBERS_DB.prepare("UPDATE consequence_review_queue SET status='awaiting-editorial-review',updated_at=? WHERE checkpoint_key=?").bind(stamp,`${contractId}:${checkpointDays}`).run();await audit(env,'consequence.assessment.created','consequence_contract',contractId,{checkpointDays,version,finding,publicationStatus,evidenceIds});return json({ok:true,id,version,publicationStatus,contractId,checkpointDays});}

export default{async fetch(request,env){if(!hasD1(env))return json({ok:false,persistent:false,error:'MEMBERS_DB unavailable'},503);const path=new URL(request.url).pathname.replace(/\/+$/,'')||'/';try{if(path==='/api/public/consequence-contracts'&&request.method==='GET')return listContracts(request,env);if(path==='/api/public/consequence-due'&&request.method==='GET')return dueQueue(env);const detail=path.match(/^\/api\/public\/consequence-contracts\/([^/]+)$/);if(detail&&request.method==='GET')return contractDetail(env,decodeURIComponent(detail[1]));if(path==='/api/admin/consequence-contracts/lock'&&request.method==='POST')return lockTerms(request,env);if(path==='/api/admin/consequence-evidence'&&request.method==='POST')return addEvidence(request,env);if(path==='/api/admin/consequence-assessment'&&request.method==='POST')return publishAssessment(request,env);return json({ok:false,error:'Not found'},404);}catch(error){return json({ok:false,error:clean(error?.message||error,1000)},500);}}};
